const KALIGHAT_INFO={id:"kalighat-painting",title:"Kalighat Painting — Bengal's Iconic Brushwork",originRegion:"Kalighat, Kolkata (Calcutta), West Bengal",eraOrigin:"19th Century Bengal (c. 1800–1930)",heritageStatus:"Celebrated folk-painting school of colonial Calcutta",signatureStyle:"Bold single-stroke line, flat unshaded washes",quickStats:[{label:"Birthplace",value:"Kalighat Temple, Kolkata",icon:"🛕"},{label:"Golden Era",value:"19th Century (c. 1800–1930)",icon:"⏳"},{label:"Medium",value:"Watercolour on Mill Paper",icon:"🎨"},{label:"Hallmark Stroke",value:"Single Unbroken Tapering Line",icon:"✒️"},{label:"Signature Palette",value:"Black, Red, Green & Yellow",icon:"🌈"},{label:"Twin Themes",value:"Divine & Social Satire",icon:"🎭"}]},HISTORY_CHAPTERS=[{title:"Roots at the Kali Ghat",period:"Late 18th – Early 19th Century",description:"Patua scroll painters migrating from rural Bengal settled along the Hooghly riverbank near the Kalighat temple, beside the sacred ghat that gave the school its name."},{title:"The Pilgrim Trade",period:"Mid 19th Century",description:"Pilgrims visiting the goddess Kali bought these cheap, quickly-made watercolours as souvenirs. Religious subjects — Kali, Durga, Shiva and the epics — dominated this early phase."},{title:"The Bold Brushwork",period:"Late 19th Century",description:"Kalighat painters refined a strikingly modern idiom: sweeping single-stroke outlines, tapering brush lines, flat unshaded washes and empty backgrounds — a sharp break from ornate court miniatures."},{title:"Social Satire",period:"1870s – 1930s",description:"Artists turned their brush on Calcutta's colonial society — the English-educated baboo, the liberated bibi, cunning priests and grasping zamindars — creating India's first school of satirical popular art."},{title:"Decline & Rediscovery",period:"1930s – Present",description:"Oleographs and photography undercut the hand-painted trade, and the school faded by the 1930s. Today museums worldwide preserve it, and contemporary artists such as Santanu Chakraverty keep the brushwork alive."}],BRUSHWORK_STEPS=[{step:1,title:"One Unbroken Stroke",description:"The painter draws each figure with a single sweep of the brush, never lifting it mid-line — a feat of control that gives the art its electric, immediate energy."},{step:2,title:"Tapering Outlines",description:"Lines swell thick at the shoulder of a figure and die away to a hair-thin point, shaping arms, necks and saris with effortless grace."},{step:3,title:"Flat, Unshaded Washes",description:"Colour is laid in even, unmodulated washes. There is no shading, no perspective — form is built entirely by the outline."},{step:4,title:"Restrained Palette",description:"Black, grey, crimson red, green, yellow and blue dominate, applied against the bare white of cheap mill-made paper."},{step:5,title:"Expressive Faces",description:"Large, heavily-lidded almond eyes, sharply arched brows and finely drawn hands carry the drama of each scene."},{step:6,title:"Empty Backgrounds",description:"Figures float on untouched paper, the emptiness focusing the eye on gesture and expression alone."}],THEMES=[{name:"Hindu Deities",category:"Divine",icon:"🕉️",description:"Kali, Durga, Ganesha, Shiva and Lakshmi were the earliest and most beloved subjects, painted as pilgrims' souvenirs at the temple ghat."},{name:"Radha–Krishna & Vaishnava Love",category:"Divine",icon:"🪈",description:"Tender scenes of Radha and Krishna, and episodes from the Vaishnava tradition, rendered with the school's signature lyric line."},{name:"The Epics",category:"Divine",icon:"📜",description:"Ramayana and Mahabharata episodes — Ravana battling Hanuman, Kichak's slaying — brought the great stories to the common man."},{name:"The Baboo & the Bibi",category:"Social Satire",icon:"🤵",description:"The English-educated Bengali gentleman with his anglicised manners was caricatured mercilessly, lampooning colonial mimicry."},{name:"Women & Domestic Life",category:"Social Satire",icon:"🏠",description:"Bibi ladies smoking hookahs, applying kohl and scolding husbands painted a lively picture of Calcutta's changing domestic world."},{name:"Greed, Priests & Zamindars",category:"Social Satire",icon:"🐱",description:"Cats stealing prawns, cunning priests and grasping landlords exposed hypocrisy — sly fables told in a single image."}],ARTIST_COMMUNITY={title:"The Patuas of Kalighat & the Living Legacy",description:"The painters were village patuas (scroll artists) who turned a temple pilgrimage trade into India's first popular urban art school. Though the original shops closed by the 1930s, Kalighat's bold line now lives on in contemporary studios — carried forward by revivalists such as Santanu Chakraverty, and treasured in collections from the Victoria Memorial to the British Museum and the Cleveland Museum of Art."},GALLERY_IMAGES=[{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Radha-_Krishna,_Kalighat_Painting.jpg",caption:"Radha–Krishna, Kalighat painting — the divine-love theme in the school's lyrical single-stroke style.",category:"Divine"},{url:"https://commons.wikimedia.org/wiki/Special:FilePath/The_demon_ravana_fighting_with_the_ape_hanuman,_1880,_kalighat_school.jpg",caption:"Ravana battling Hanuman (c. 1880) — an epic Ramayana scene from the Kalighat school.",category:"Divine"},{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Yashoda_coaxing_baby_Krishna,_Kalighat_Painting.jpg",caption:"Yashoda coaxing baby Krishna — domestic devotion rendered in flat, unshaded washes.",category:"Divine"},{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Kalighat_Painting_Calcutta_19th_Century_-_Woman_Striking_Man_With_Broom.jpg",caption:"Woman striking a man with a broom — a famous Kalighat social-commentary panel turning the tables on the baboo.",category:"Social Satire"},{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Untitled_(Cat_Stealing_Prawn).jpg",caption:"Cat stealing a prawn — the sly Kalighat fable on greed, hypocrisy and the Bengali kitchen.",category:"Social Satire"}],REFERENCES=[{text:"Britannica — Kalighat painting: origin, style and social commentary.",link:"https://www.britannica.com/art/Kalighat-painting"},{text:"Victoria and Albert Museum — Kalighat paintings of 19th-century Calcutta.",link:"https://www.vam.ac.uk/articles/kalighat-paintings"},{text:"Cleveland Museum of Art — Kalighat paintings in the collection (e.g. Trivikramapada, acc. 2003.165).",link:"https://www.clevelandart.org/art/2003.165"},{text:"Sahapedia — Kalighat paintings: faith, craft and satire.",link:"https://www.sahapedia.org/kalighat-paintings"}];"undefined"!=typeof module&&module.exports&&(module.exports={KALIGHAT_INFO:KALIGHAT_INFO,HISTORY_CHAPTERS:HISTORY_CHAPTERS,BRUSHWORK_STEPS:BRUSHWORK_STEPS,THEMES:THEMES,ARTIST_COMMUNITY:ARTIST_COMMUNITY,GALLERY_IMAGES:GALLERY_IMAGES,REFERENCES:REFERENCES});